def count_vowels(s: str) -> int:
    vowels = 'aeiouy'
    count = 0
    for char in s:
        if char.lower() in vowels:
            count += 1
    return count

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def flatten(items: list) -> list:
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def fib(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib(n - 1) + fib(n - 2)

def is_palindrome(s: str) -> bool:
    s = s.replace(" ", "").lower()
    return s == s[::-1]

def max_diff(nums: list) -> int:
    if len(nums) < 2:
        return 0

    max_diff = nums[1] - nums[0]
    for i in range(1, len(nums)):
        for j in range(i + 1, len(nums)):
            diff = nums[j] - nums[i]
            if diff > max_diff:
                max_diff = diff

    return max_diff

def unique_order(items: list) -> list:
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def caesar(s: str, k: int) -> str:
    result = ""
    for char in s:
        if char.isalpha():
            shift = k % 26
            if char.isupper():
                result += chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            else:
                result += chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
        else:
            result += char
    return result

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def strip_vowels(s: str) -> str:
    vowels = 'aeiouy'
    return ''.join(c for c in s if c.lower() not in vowels)

def char_freq(s: str) -> dict:
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    return freq

def brackets_balanced(s: str) -> bool:
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or \
               (char == ')' and stack[-1] != '(') or \
               (char == ']' and stack[-1] != '[') or \
               (char == '}' and stack[-1] != '{'):
                return False
            stack.pop()
    return len(stack) == 0

def two_sum(nums: list, target: int) -> bool:
    seen = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            return True
        seen.add(num)
    return False

def rotate(nums: list, k: int) -> list:
    if k < 0:
        raise ValueError("k must be non-negative")
    k = k % len(nums)
    return nums[-k:] + nums[:-k]

def count_inversions(nums: list) -> int:
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] > nums[j]:
                count += 1
    return count

def digit_root(n: int) -> int:
    while n >= 10:
        n = sum(int(digit) for digit in str(n))
    return n
